// UI. Malformed byte files are explicitly declared negative fixtures. No product
// library/compiler/planner is imported as an expected-result oracle.
assert.equal(assets.length,18,'Exactly the reviewed18 actual served assets');
assert(assets.includes('table-xlsx.js')&&assets.includes('table-export-ui.js'));
assert(assets.includes('table-view-portability.js'));
const mainColumns=['url','status','title_count','title_pixels'],responseColumns=['url','requested_url','response_index','status'];
const L=rule=>({kind:'rule',rule}),mainExpression={kind:'any',children:[L({key:'title_count',op:'min',min:2}),L({key:'title_text',op:'contains',text:'CAFE\u0301'})]};
const v1View={sectionFilter:'duplicate',search:'CAFÉ',rules:[{key:'title_count',op:'min',min:1}],sort:{key:'title_text',direction:-1},visibleKeys:mainColumns};
const v2View={sectionFilter:'duplicate',search:'CAFÉ',expression:mainExpression,sort:{key:'title_text',direction:-1},visibleKeys:mainColumns};
const records={},key=v=>'open-seo-spider.table-views.v'+v,prefixFor=v=>v===1?'table-view-':'table-expression-view-',modeFor=v=>v===1?'simple':'grouped';
const selector=(v,suffix)=>'#'+prefixFor(v)+suffix;
async function raw(v,target=page){return target.evaluate(k=>localStorage.getItem(k),key(v));}
async function bothRaw(){return{v1:await raw(1),v2:await raw(2)};}
async function storageMap(excludedPrefix=''){return page.evaluate(prefix=>Object.fromEntries(Object.keys(localStorage).filter(name=>!prefix||!name.startsWith(prefix)).sort().map(name=>[name,localStorage.getItem(name)])),excludedPrefix);}
function decode(rawValue,v){const value=rawValue===null?{engine:'open-seo-spider/table-views-v'+v,version:v,entries:[]}:JSON.parse(rawValue);assert.deepEqual(Object.keys(value),['engine','version','entries']);assert.equal(value.engine,'open-seo-spider/table-views-v'+v);assert.equal(value.version,v);assert(Array.isArray(value.entries));return value;}
async function saveCatalog(v,label){const value=await raw(v),file=artifactPath('catalog-v'+v+'-'+String(catalogSnapshots.length).padStart(3,'0')+'.json');assert(value!==null);fs.writeFileSync(file,value);catalogSnapshots.push({version:v,label,path:file,bytes:Buffer.byteLength(value),sha256:sha(Buffer.from(value)),entries:decode(value,v).entries});return value;}
async function snapshot(){return page.evaluate(()=>({owner:document.getElementById('crawl-history').value,section:document.querySelector('[data-section][aria-current="page"]')?.dataset.section,mode:document.getElementById('table-rule-mode').value,filter:document.getElementById('table-filter').value,search:document.getElementById('table-search').value,sort:{key:document.getElementById('table-sort-column').value,direction:Number(document.getElementById('table-sort-direction').value)},columns:[...document.querySelectorAll('#results-table thead [data-sort]')].map(n=>n.dataset.sort),rules:[...document.querySelectorAll('#table-rules li[data-table-rule-index]')].map(n=>n.textContent),nodes:[...document.querySelectorAll('#table-expression-editor [data-expression-kind]')].map(n=>({path:n.dataset.expressionPath,kind:n.dataset.expressionKind,text:n.textContent})),page:document.getElementById('page-label').textContent,rows:[...document.querySelectorAll('#results-table tbody tr[data-row]')].map(n=>[...n.querySelectorAll('td')].map(c=>c.textContent.trim()))}));}
async function clearQuery(){
  await options();const activeMode=await page.inputValue('#table-rule-mode'),clear=page.locator('#table-rules-clear');assert(['simple','grouped'].includes(activeMode));if(await clear.isEnabled())await clear.click();assert.equal(await clear.isDisabled(),true,'The actual Clear control confirms no active rule or rule error');assert.equal(await page.inputValue('#table-rule-mode'),activeMode);
  assert.equal(await page.locator('#table-rules li[data-table-rule-index]').count(),0);
  // Owner reset leaves old grouped markup hidden until the next grouped render.
  // Count the active rule subtree; inactive markup is not an accepted expression.
  if(activeMode==='simple')assert.equal(await page.locator('#table-expression-editor').isHidden(),true);else{assert.equal(await page.locator('#table-expression-editor').isVisible(),true);assert.equal(await page.locator('#table-expression-editor [data-expression-kind]').count(),0);}
  for(const id of['table-explorer-error','table-expression-error']){assert.equal(await page.locator('#'+id).isHidden(),true);assert.equal((await page.locator('#'+id).textContent()).trim(),'');}
  await page.fill('#table-search','');await page.selectOption('#table-filter','all');
}
async function mode(v){await options();if(await page.inputValue('#table-rule-mode')!==modeFor(v)){await clearQuery();await page.selectOption('#table-rule-mode',modeFor(v));}assert.equal(await page.inputValue('#table-rule-mode'),modeFor(v));}
async function library(v){await options();assert.equal(await page.inputValue('#table-rule-mode'),modeFor(v));await page.locator(v===1?'#table-views':'#table-expression-views').waitFor({state:'visible'});}
async function reload(v){await library(v);const sectionName=await page.locator('[data-section][aria-current="page"]').getAttribute('data-section');await page.click(selector(v,'refresh'));await page.waitForFunction(({key,prefix,section})=>{try{const raw=localStorage.getItem(key),expected=raw===null?[]:JSON.parse(raw).entries.filter(x=>x.section===section).map(x=>x.id),actual=[...document.querySelectorAll('#'+prefix+'select option')].map(x=>x.value).filter(Boolean);return JSON.stringify(actual)===JSON.stringify(expected);}catch{return false;}},{key:key(v),prefix:prefixFor(v),section:sectionName});}
async function select(v,id){await library(v);await page.locator(selector(v,'select')+' option[value="'+id+'"]').waitFor({state:'attached'});await page.selectOption(selector(v,'select'),id);}
async function barrier(v){await page.evaluate(name=>navigator.locks.request(name,{mode:'exclusive'},()=>null),key(v)+':mutation');}
async function configureMain(v){await section('titles');await mode(v);await clearQuery();if(v===1)await rule('title_count','min',{min:1});else{await rule('title_count','min',{min:2});await page.selectOption('#table-expression-target','root');await page.click('#table-expression-wrap-any');await page.selectOption('#table-expression-target','root');await rule('title_text','contains',{text:'CAFE\u0301'});}await page.selectOption('#table-filter','duplicate');await page.fill('#table-search','CAFÉ');await sort('title_text',-1);await columns(mainColumns);}
function expected(job,kind='main',urlSort=false){const rows=titleRows(job);assert.equal(rows.length,152);if(kind==='all')return ordered(rows,'url',1);const members=new Set(Array.from({length:151},(_,i)=>i).filter(i=>{const n=i===150?149:i;return n>=4&&n%5!==0;}).map(i=>'/items/'+String(i).padStart(4,'0'))),result=rows.filter(row=>[...members].some(suffix=>row.url.endsWith(suffix)));assert.equal(result.length,118);return ordered(result,urlSort?'url':'title_text',urlSort?1:-1);}
function responseTwins(job){const a=job.report.pages.find(x=>x.url.endsWith('/items/0149')),b=job.report.pages.find(x=>x.url.endsWith('/items/0150'));assert(a&&b);assert.equal(b.status,302);assert.equal(b.final_url,a.url);return[a,b].map(x=>({url:a.url,requested_url:x.url,response_index:x.redirect_chain.length+1,status:200,page:x}));}
async function configureResponses(v,job){await section('responses');await mode(v);await clearQuery();const target=job.report.pages.find(x=>x.url.endsWith('/items/0149')).url;await rule('url','equals',{text:target});let view;if(v===1)view={sectionFilter:'all',search:'',rules:[{key:'url',op:'equals',text:target}],sort:{key:'url',direction:1},visibleKeys:responseColumns};else{await page.selectOption('#table-expression-target','root');await page.click('#table-expression-wrap-any');await page.selectOption('#table-expression-target','root');await rule('status','range',{min:200,max:200});await page.selectOption('#table-expression-target','1');await page.click('#table-expression-wrap-all');await page.selectOption('#table-expression-target','1');await rule('requested_url','contains',{text:'/items/0150'});view={sectionFilter:'all',search:'',expression:{kind:'any',children:[L({key:'url',op:'equals',text:target}),{kind:'all',children:[L({key:'status',op:'range',min:200,max:200}),L({key:'requested_url',op:'contains',text:'/items/0150'})]}]},sort:{key:'url',direction:1},visibleKeys:responseColumns};}await sort('url',1);await columns(responseColumns);await exact(responseTwins(job),responseColumns,'v'+v+' genuine equal observed URL occurrences before portable file');return view;}
async function create(v,name,view){await library(v);const before=await bothRaw(),prior=await snapshot();await page.fill(selector(v,'name'),name);await page.click(selector(v,'create'));await barrier(v);await until(async()=>decode(await raw(v),v).entries.length===decode(before['v'+v],v).entries.length+1,'actual v'+v+' UI Create');const value=decode(await raw(v),v),entry=value.entries.find(x=>x.name===name);assert(entry);assert.match(entry.id,/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/);assert.deepEqual(entry.view,view);assert.equal(entry.section,prior.section);assert.equal(entry.query_semantics,'open-seo-spider/table-query-v'+v);assert.deepEqual(await snapshot(),prior,'Create never applies');assert.equal(await raw(v===1?2:1),before['v'+(v===1?2:1)]);return entry;}
async function apply(v,entry,job,kind='main',sectionName='titles'){await select(v,entry.id);const rows=sectionName==='responses'?responseTwins(job):expected(job,kind,kind==='main'&&entry.view.sort.key==='url'),keys=entry.view.visibleKeys,first=rows.length?'1–'+Math.min(50,rows.length)+' von '+rows.length:'Keine Ergebnisse';await page.click(selector(v,'apply'));await page.waitForFunction(({prefix,name,view,first})=>document.getElementById(prefix+'active').textContent==='Angewendet: '+name&&document.getElementById('table-filter').value===view.sectionFilter&&document.getElementById('table-search').value===view.search&&document.getElementById('table-sort-column').value===view.sort.key&&document.getElementById('table-sort-direction').value===String(view.sort.direction)&&document.getElementById('page-prev').disabled&&document.getElementById('page-label').textContent===first&&JSON.stringify([...document.querySelectorAll('#results-table thead [data-sort]')].map(x=>x.dataset.sort))===JSON.stringify(view.visibleKeys),{prefix:prefixFor(v),name:entry.name,view:entry.view,first});assert.equal(await page.locator('#page-prev').isDisabled(),true,'Explicit Apply resets first page before any row helper');assert.equal(await page.locator('#page-label').textContent(),first);await exact(rows,keys,'v'+v+' explicit saved Apply '+entry.name);return rows;}
async function exportJSON(v,scope,label){await library(v);const before=await bothRaw(),prior=await snapshot(),stored=decode(before['v'+v],v),id=await page.inputValue(selector(v,'select'));if(scope==='selected')assert(id);const wait=page.waitForEvent('download');await page.click(selector(v,'export-'+scope));const actual=await wait,file=artifactPath(label+'.json');assert.equal(actual.suggestedFilename(),'open-seo-spider-table-views-v'+v+(scope==='selected'?'-selected':'')+'.json');await actual.saveAs(file);const content=fs.readFileSync(file),text=new TextDecoder('utf-8',{fatal:true}).decode(content),value=JSON.parse(text);assert.notEqual(content.subarray(0,3).toString('hex'),'efbbbf');assert(!text.endsWith('\n')&&!text.endsWith('\r'));assert.deepEqual(value,{engine:stored.engine,version:v,entries:scope==='selected'?stored.entries.filter(x=>x.id===id):stored.entries});assert.deepEqual(await bothRaw(),before,'Definition export writes neither catalog');assert.deepEqual(await snapshot(),prior,'Definition export changes no accepted query or rows');const record={version:v,origin:new URL(page.url()).origin,scope,label,path:file,bytes:content.length,sha256:sha(content),suggested:actual.suggestedFilename(),entries:value.entries,value,content,source:'actual_browser_definition_download'};jsonFiles.push({...record,content:undefined});return record;}
async function preview(v,file){await library(v);const before=await bothRaw(),prior=await snapshot();await page.setInputFiles(selector(v,'import-file'),file.path);await page.locator(selector(v,'import-preview')).waitFor({state:'visible'});await page.waitForFunction(({prefix,count})=>document.querySelectorAll('#'+prefix+'import-items [data-table-import-id]').length===count,{prefix:prefixFor(v),count:file.value.entries.length});const actual=await page.locator(selector(v,'import-items')+' [data-table-import-id]').evaluateAll(rows=>rows.map(row=>{const pre=row.querySelector('pre');return{id:row.dataset.tableImportId,definition:JSON.parse(pre.textContent),tabindex:pre.tabIndex,aria_label:pre.getAttribute('aria-label')};}));assert.deepEqual(actual.map(({id,definition})=>({id,definition})),file.value.entries.map(entry=>({id:entry.id,definition:entry})));for(const row of actual){assert.equal(row.tabindex,0,'Complete definition PRE is keyboard focusable');assert.equal(row.aria_label,'Vollständige Ansichtsdefinition: '+row.definition.name+' · Bereich: '+row.definition.section,'Complete preview definition has the exact name/section accessible label');}assert.deepEqual(await bothRaw(),before,'Preview is read-only');assert.deepEqual(await snapshot(),prior,'Preview never auto-applies');return{before,prior};}
