async function confirm(v,label,{unchanged=false}={}){const before=await bothRaw(),prior=await snapshot();assert.equal(await page.locator(selector(v,'import-confirm')).isEnabled(),true,'Whole-catalog preview must be valid before explicit Confirm');await page.click(selector(v,'import-confirm'));await barrier(v);await page.locator(selector(v,'import-preview')).waitFor({state:'hidden'});assert.equal(await page.locator(selector(v,'error')).isVisible(),false);if(unchanged)assert.deepEqual(await bothRaw(),before,'No-op import preserves exact original catalog bytes');else assert.equal(await raw(v===1?2:1),before['v'+(v===1?2:1)],'Import changes only explicitly selected catalog version');assert.deepEqual(await snapshot(),prior,'Import never applies any definition');imports.push({version:v,label,source:'actual_download_file_explicit_preview_confirm',before_sha256:before['v'+v]===null?null:sha(Buffer.from(before['v'+v])),after_sha256:(await raw(v))===null?null:sha(Buffer.from(await raw(v))),noop:unchanged,query_sha256:sha(Buffer.from(JSON.stringify(prior)))});}
async function cancel(v){const before=await bothRaw(),prior=await snapshot();await page.click(selector(v,'import-cancel'));await page.locator(selector(v,'import-preview')).waitFor({state:'hidden'});assert.deepEqual(await bothRaw(),before);assert.deepEqual(await snapshot(),prior);}
async function reset(v){const before=await bothRaw(),prior=await snapshot();await page.click(selector(v,'reset'));await page.locator(selector(v,'reset-confirmation')).waitFor({state:'visible'});assert.deepEqual(await bothRaw(),before);await page.click(selector(v,'reset-confirm'));await barrier(v);await until(async()=>await raw(v)===null,'explicit v'+v+' catalog reset');assert.equal(await raw(v===1?2:1),before['v'+(v===1?2:1)]);assert.deepEqual(await snapshot(),prior,'Reset removes definitions only');}
async function rejectFile(v,label,content){await library(v);const file=artifactPath('declared-negative-v'+v+'-'+label+'.bin');fs.writeFileSync(file,content);const before=await bothRaw(),prior=await snapshot();await page.setInputFiles(selector(v,'import-file'),file);await page.locator(selector(v,'error')).waitFor({state:'visible'});const reason=await page.locator(selector(v,'error')).textContent(),expectedReason={'invalid-utf8':'ungültige UTF-8','corrupt-json':'gültiges JSON','empty-file':'nichtleere JSON-Datei','oversize-file':'Katalog-Bytegrenze','wrong-engine-actual-other-mode-download':'anderen Filtermodus'}[label];assert(expectedReason&&reason.includes(expectedReason),'The actual file must fail for its declared reason: '+label);assert.equal(await page.locator(selector(v,'import-confirm')).isEnabled(),false);assert.deepEqual(await bothRaw(),before);assert.deepEqual(await snapshot(),prior);negativeControls.push({kind:label,version:v,source:'explicit_declared_negative_file_bytes_not_positive_definition_proof',file,bytes:content.length,sha256:sha(content),visible_error:await page.locator(selector(v,'error')).textContent()});}

